head.script:
scwin.vScrenID = "ULDFIL35700.xml";
// 전역 변수 선언
scwin.method = "";
scwin.pageIndex = "";
scwin.mkt = "1"; //시장구분
scwin.listTp = "2"; //상장방식
scwin.kk = "1"; //수수료구분
scwin.bkk = ""; //이전 수수료구분

scwin.onpageload = function() {

    //grid 제어
    grd_list.setColumnVisible("issueCode", false);
    grd_list.setColumnVisible("trust_count", false);
    grd_list.setColumnVisible("commission", false);
    scwin.changeType("1", "2");

    //합계 보여주기
    sum1.setStyle("display", "");
    sum2.setStyle("display", "");
    sum3.setStyle("display", "");
    sum4.setStyle("display", "");
    sum5.setStyle("display", "none");
    sum6.setStyle("display", "none");
};

/* [수수료계산] 전환 진행중 */

