/* [수수료계산] 시장구분 선택 onchange */
scwin.rdo_gubun1_onchange = function (info) {
    scwin.checkValueMkt(info.newValue);
};

/* [수수료계산] 상장방식 선택 onchange */
scwin.rdo_gubun2_onchange = function (info) {
    // if(scwin.mkt == "2"){
	// 	layer_popup('#layer1');
	// }
    //TODO: 이거말고 비활성화 된 cell 클릭했을때 뜨는 alert도 필요

    scwin.checkValue();
};

/* [수수료계산] 수수료구분 선택 onchange */
scwin.rdo_gubun3_onchange = function (info) {
    scwin.checkValue();
};

/* [수수료계산] 시장구분 선택 */
scwin.checkValueMkt = function(mkt){

    scwin.mkt = mkt;

    scwin.changeStockType(mkt);

    scwin.changeStyle(mkt);

	//유가증권시장 무액면주식 체크/해제시
    // fnCheckGubun(mkt);

    // scwin.changeStockType(mkt);

    scwin.changeType(mkt,scwin.kk);
}

/* [수수료계산] 상장방식, 수수료구분 선택 */
scwin.checkValue = function(){
	// var mkt=""; //시장구분
	let mathTp = "올림";
	/*이전 radio 버튼 값 저장 */
	// document.all.bkk.value=scwin.kk;
    scwin.bkk = scwin.kk;

    let mkt = "";
    let listTp="";//상장방식        
    let kk=""; //수수료구분

    mkt = rdo_gubun1.getValue();
    listTp = rdo_gubun2.getValue();
    kk = rdo_gubun3.getValue();

  	if(mkt === "1") {  		//유가

    } 
	else if(mkt === "2") //코스닥
	{		
    }
    else if(mkt === "3") //증권시장
    {
  		if(kk===3) {
  			mathTp = "버림";
  		}
    	scwin.reset();
    }
    else if(mkt === "D") {  	// 상장수수료 (신종증권) 기능 추가 2023.08.xx - 유가증권>신규상장>수익증권 참조
  		//상장수수료 (신종증권)
  		listTp = "";//상장방식
    }

  	// scwin.changeStockType(mkt,kk);

  	scwin.changeType(mkt,kk);

  	document.all.mathTp.innerText = mathTp;
	scwin.listTp = listTp;
    scwin.kk = kk;


    if(mkt === "3" && kk === "1"){
    	// document.all.tdNm4.innerText ="* 상장할 신탁원본액";
        grd_list.setHeaderValue("h_tdNm4", "* 상장할 신탁원본액");
    } else if(mkt === "3" && kk === "2"){
    	// document.all.tdNm4.innerText ="* 발행원본액";
        grd_list.setHeaderValue("h_tdNm4", "* 발행원본액");
    } else if(mkt === "3" && kk === "3"){
    	// document.all.tdNm4.innerText ="* 발행총액";
        grd_list.setHeaderValue("h_tdNm4", "* 발행총액");
    }

    //유가증권시장 무액면주식 체크/해제시
    //fnCheckGubun(mkt);

    //시장구분, 상장방색, 수수료구분 값이 변경되면 총상장금액, 상장수수료합계, 상장수수료 최저한도, 부과상장수수료 항목값 초기화
    ibx_totListAmt.setValue("");
    ibx_listCommSum.setValue("");
    ibx_listCommSumMin.setValue("");
    ibx_listCommSumAdd.setValue("");
}

/* [수수료계산] 시장구분, 상장방식, 수수료구분 맞게 Grid 활성/비활성화 처리 */
scwin.changeType = function(mkt,kk) {

    grd_list.setColumnReadOnly("stock_type", true); //종류 컬럼은 readonly

    //번호 1~2번행 입력창 활성화
    for(let i=0; i < 2; i++) {
        grd_list.setCellReadOnly(i, "stock_count", false);
        grd_list.setCellBackgroundColor(i, "stock_count", "#ffffff");
        grd_list.setCellReadOnly(i, "parval", false);
        grd_list.setCellBackgroundColor(i, "parval", "#ffffff");
        grd_list.setCellReadOnly(i, "list_amt", false);
        grd_list.setCellBackgroundColor(i, "list_amt", "#ffffff");
    }

	if(mkt === '1') {	//유가

		if(kk === "3"){
            dlt_calList.setCellData(0, "stock_type", "");
            dlt_calList.setCellData(1, "stock_type", "");

            //번호 3~10번행 입력창 활성화
			for(let i=2; i < 10; i++) {
                grd_list.setCellReadOnly(i, "stock_count", false);
                grd_list.setCellBackgroundColor(i, "stock_count", "#ffffff");
                grd_list.setCellReadOnly(i, "parval", false);
                grd_list.setCellBackgroundColor(i, "parval", "#ffffff");
                grd_list.setCellReadOnly(i, "list_amt", false);
                grd_list.setCellBackgroundColor(i, "list_amt", "#ffffff");
				scwin.reset();
			}

		}else{
            dlt_calList.setCellData(0, "stock_type", "보통주권");
            dlt_calList.setCellData(1, "stock_type", "종류주권");
			//번호 3~10번행 입력창 비활성화
			for(let i=2; i < 10; i++) {
                grd_list.setCellReadOnly(i, "stock_count", true);
                grd_list.setCellBackgroundColor(i, "stock_count", "#f0f0f0");
                grd_list.setCellReadOnly(i, "parval", true);
                grd_list.setCellBackgroundColor(i, "parval", "#f0f0f0");
                grd_list.setCellReadOnly(i, "list_amt", true);
                grd_list.setCellBackgroundColor(i, "list_amt", "#f0f0f0");
				if(scwin.bkk === "3"){
					scwin.reset();
				}
			}
		}
	} else if(mkt === '2') {	//코스닥

		//번호 2~10번행 입력창 비활성화
		for(let i=1; i < 10; i++) {
            grd_list.setCellReadOnly(i, "stock_count", true);
            grd_list.setCellBackgroundColor(i, "stock_count", "#f0f0f0");
            grd_list.setCellReadOnly(i, "parval", true);
            grd_list.setCellBackgroundColor(i, "parval", "#f0f0f0");
            grd_list.setCellReadOnly(i, "list_amt", true);
            grd_list.setCellBackgroundColor(i, "list_amt", "#f0f0f0");
		}
	}
	else if(mkt === 'D') {	//신종증권
        dlt_calList.setCellData(0, "stock_type", "");
        dlt_calList.setCellData(1, "stock_type", "");

        //번호 3~10번행 입력창 활성화
		for(let i=2; i < 10; i++) {
            grd_list.setCellReadOnly(i, "stock_count", false);
            grd_list.setCellBackgroundColor(i, "stock_count", "#ffffff");
            grd_list.setCellReadOnly(i, "parval", false);
            grd_list.setCellBackgroundColor(i, "parval", "#ffffff");
            grd_list.setCellReadOnly(i, "list_amt", false);
            grd_list.setCellBackgroundColor(i, "list_amt", "#ffffff");
			scwin.reset()
		}
	}
	else {			//코스닥 외

		//번호 2~10번행 입력창 활성화
		for(let i=1; i < 10; i++) {
            grd_list.setCellReadOnly(i, "stock_count", false);
            grd_list.setCellBackgroundColor(i, "stock_count", "#ffffff");
            grd_list.setCellReadOnly(i, "parval", false);
            grd_list.setCellBackgroundColor(i, "parval", "#ffffff");
            grd_list.setCellReadOnly(i, "list_amt", false);
            grd_list.setCellBackgroundColor(i, "list_amt", "#ffffff");
		}
	}
}

/* [수수료계산] 시장구분 선택 */
scwin.changeStockType = function(mkt) {
    rdo_gubun2.removeAll();
    rdo_gubun3.removeAll();
    if (mkt === "1") {
        // 유가증권시장
        rdo_gubun2.addItem("1", "신규상장");
        rdo_gubun2.addItem("2", "추가/변경/재상장");
        rdo_gubun2.setValue("2");

        rdo_gubun3.addItem("1", "보통주권/외국주권/종류주권/기업인수목적회사주권");
        rdo_gubun3.addItem("2", "집합투자증권");
        rdo_gubun3.addItem("3", "수익증권");
        rdo_gubun3.addItem("4", "신주인수권증권");
        rdo_gubun3.setValue("1");
    } else if (mkt === "2") {
        // 코스닥시장
        rdo_gubun2.addItem("1", "신규상장");
        rdo_gubun2.addItem("2", "추가/재상장");
        rdo_gubun2.setValue("2");

        rdo_gubun3.addItem("1", "주권/외국주권/외국주식예탁증권(DR)");
        rdo_gubun3.addItem("6", "신주인수권증권");
        rdo_gubun3.setValue("1");
    } else if (mkt === "3") {
        // 증권상품
        rdo_gubun3.addItem("1", "ETF");
        rdo_gubun3.addItem("2", "ETN");
        rdo_gubun3.addItem("3", "ELW");
        rdo_gubun3.addItem("4", "상장형 수익증권");
        rdo_gubun3.setValue("1");
    } else if (mkt === "D") {
        // 신종증권
        rdo_gubun3.addItem("1", "신탁수익증권");
        rdo_gubun3.addItem("2", "투자계약증권");
        rdo_gubun3.setValue("1");
    }
}

