/* [수수료계산] 초기화 */
scwin.reset = function(){

    dlt_calList.reset();

    ibx_totListAmt.setValue("");
    ibx_listCommSum.setValue("");
    ibx_listCommSumMin.setValue("");
    ibx_listCommSumAdd.setValue("");

    ibx_totListAmtTrust.setValue("");
    ibx_listCommSumTrust.setValue("");

	// $('input:checkbox[name="checkGubun1"]').attr('checked', false);
    // '무액면주식' 이라는데 사용하지 않는것 같음

	dataArr = null;
	dataArr_trust = null;
}

/* [수수료계산] 계산 - 기본 */
scwin.taxCalc = function(){
	dataArr = new Array;

	// var calc = document.all;

    for(let i=0; i<10; i++) {
        dataArr[i] = {stock_count: dlt_calList.getCellData(i, "stock_count"), parval: dlt_calList.getCellData(i, "parval"), list_amt: ''};
    }

	const type = scwin.kk;
	let listTp = scwin.listTp;

	let tot_list = 0;
	let list_comm_sum = 0;
	let list_comm_sum_add = 0;

	let inputFlag = false;

	//유가계산	
	if(scwin.mkt === "1") {

		for(i = 0; i < dataArr.length; i++){

			// if(dataArr[i].stock_count != "" && dataArr[i].parval != "" &&  document.all.checkGubun1.checked == false){			
            if(dataArr[i].stock_count !== "" && dataArr[i].parval !== ""){		
				inputFlag = true;

				//상장금액 계산
				dataArr[i].list_amt = parseInt(delComma(dataArr[i].stock_count))*parseInt(delComma(dataArr[i].parval));

				//총상장금액 계산
				tot_list = eval(tot_list) + eval(dataArr[i].list_amt);

				//건별 상장수수료 구하기 start //////////////////////////////////////////////
				let rt_rate = "0.0";
				let rt_rate2 = "0.0";


				if(listTp === "1"){ // 상장방식 - 신규상장 
					//주권상장수수료계산 구해오기
					//보통주권 / 외국주권 / 종류주권 / 기업인수목적회사주권 수수료
					if(scwin.kk === "1") {
						rt_rate = rate_Stcok_1(tot_list);
						list_comm_sum = Math.round(rt_rate);
						rt_rate2 = rate_Stcok_1(dataArr[i].list_amt);
						list_comm_sum_add = list_comm_sum_add+eval(rt_rate2);
					}
					//집합투자증권 수수료
					else if(scwin.kk === "2") {
						rt_rate = rate_Stcok_1(tot_list);
