/* [수수료계산] 계산 - 증권상품 */
scwin.taxCalcTrust = function()
{
	dataArr_trust = new Array;
	const calc_trust = document.all;

    for(let i=0; i<10; i++) {
        dataArr_trust[i] = {issueCode: dlt_calList.getCellData(i, "issueCode"), trust_count: dlt_calList.getCellData(i, "trust_count"), trust_comm: dlt_calList.getCellData(i, "commission")};
    }

	let tot_list = 0; //상장할 금액
	let list_comm_sum = 0; //총 수수료
	let inputFlag = false;

	for(i = 0; i < dataArr_trust.length; i++){

		if(dataArr_trust[i].trust_count !== ""){			

			inputFlag =  true;

			//총신탁원본액  계산
			tot_list = eval(tot_list) + eval(parseInt(delComma(dataArr_trust[i].trust_count)));

			//건별수수료 구하기 
			let rt_rate = "0.0";

			if(scwin.kk === "3") {
				dataArr_trust[i].trust_comm = Math.floor(rate_comm_elw(parseInt(delComma(dataArr_trust[i].trust_count)))/100)*100;
			} else {
				dataArr_trust[i].trust_comm = Math.floor(rate_comm(parseInt(delComma(dataArr_trust[i].trust_count)))/100)*100;
			}

			list_comm_sum = eval(list_comm_sum) + eval(dataArr_trust[i].trust_comm);

		}
	}

	if(inputFlag) {

        for(let i=0; i<10; i++) {
            dlt_calList.setCellData(i, "commission", dataArr_trust[i].trust_comm);
        }

		// calc_trust.tot_list_amt_trust.value =  tot_list; numFormat(calc_trust.tot_list_amt_trust);
        ibx_totListAmtTrust.setValue(tot_list);
		// calc_trust.list_comm_sum_trust.value = list_comm_sum; numFormat(calc_trust.list_comm_sum_trust);
        ibx_listCommSumTrust.setValue(list_comm_sum);

	}
	else {
		alert('계산할 항목을 입력해주세요.');
	}
}

/* [수수료계산] 콤마 삭제 */
function delComma(obj){
	return obj.replace(/,/g, "");
}

/* [수수료계산] 코스닥상장수수료 */
function rate_konex(i)
{
	let rate = "0.0";

	if(i<=10000000000.0)
	{
		rate = Math.ceil(i/1000000000.0)*30000.0;
	}
	else if(i>10000000000.0 && i<=30000000000.0)
	{
		rate = 300000.0 + Math.ceil((i - 10000000000.0 )/1000000000.0) *25000.0;
	}
	else if(i>30000000000.0 && i<=50000000000.0)
	{
		rate = 800000.0 + Math.ceil((i - 30000000000.0 )/1000000000.0) *20000.0;
	}
	else if(i>50000000000.0 && i<=70000000000.0)
	{
		rate = 1200000.0 + Math.ceil((i - 50000000000.0 )/1000000000.0) *15000.0;
	}
	else if(i>70000000000.0 && i<=100000000000.0)
	{
		rate = 1500000.0 + Math.ceil((i - 70000000000.0 )/1000000000.0) *10000.0;
	}
	else if(i>100000000000.0 && i<=200000000000.0)
	{
		rate = 1800000.0 + Math.ceil((i - 100000000000.0 )/1000000000.0) *5000.0;
	}
	else if(i>200000000000.0 && i<=500000000000.0)
	{
		rate = 2300000.0 + Math.ceil((i - 200000000000.0 )/1000000000.0) * 2500.0;
	}
	else if(i>500000000000.0)
	{
		rate = 3050000.0 + Math.ceil((i - 500000000000.0 )/1000000000.0) * 500.0;
	}

	return rate;
} 

/* [수수료계산] 코스닥상장수수료-신규상장 */
function rate_kosdaq_1(i,type)
{
	let rate = "0.0";

	if(i<=50000000000.0)
	{
		rate = 1000000;
	}
	else if(i>50000000000.0 && i<=70000000000.0)
	{
		rate = 5000000.0 + Math.ceil((i - 50000000000.0 )/1000000000.0) * 70000.0;
	}
	else if(i>70000000000.0 && i<=100000000000.0)
	{
		rate = 6400000.0 + Math.ceil((i - 70000000000.0 )/1000000000.0) * 60000.0;
	}
	else if(i>100000000000.0 && i<=200000000000.0)
	{
		rate = 8200000.0 + Math.ceil((i - 100000000000.0 )/1000000000.0) * 50000.0;
	}
	else if(i>200000000000.0 && i<=300000000000.0)
	{
		rate = 13200000.0 + Math.ceil((i - 200000000000.0 )/1000000000.0) * 40000.0;
	}
	else if(i>300000000000.0 && i<=400000000000.0)
	{
		rate = 17200000.0 + Math.ceil((i - 300000000000.0 )/1000000000.0) * 30000.0;
	}
	else if(i>400000000000.0 && i<=500000000000.0)
	{
		rate = 20200000.0 + Math.ceil((i - 400000000000.0 )/1000000000.0) * 20000.0;
	}
	else if(i>500000000000.0)
	{
		rate = 22200000.0 + Math.ceil((i - 500000000000.0 )/1000000000.0) * 10000.0;
	}	

	if(rate > 200000000){
		rate = "200000000";	 //최고한도액 2억원
	}

	if(type > 3) //신주인수권증권
	{
		rate = Math.floor(rate/3/100) * 100;
	}

	return rate;
} 

/* [수수료계산] 코스닥상장수수료-추가/재상장 */
function rate_kosdaq_2(i,type)
{
	let rate = "0.0";

	if(i<=10000000000.0)
	{
		rate = Math.ceil(i/1000000000.0) * 250000.0;
	}
	else if(i>10000000000.0 && i<=30000000000.0)
	{
		rate = 2500000.0 + Math.ceil((i - 10000000000.0 )/1000000000.0) * 90000.0;
	}
	else if(i>30000000000.0 && i<=50000000000.0)
	{
		rate = 4300000.0 + Math.ceil((i - 30000000000.0 )/1000000000.0) * 80000.0;
	}
	else if(i>50000000000.0 && i<=70000000000.0)
	{
		rate = 5900000.0 + Math.ceil((i - 50000000000.0 )/1000000000.0) * 70000.0;
	}
	else if(i>70000000000.0 && i<=100000000000.0)
	{
		rate = 7300000.0 + Math.ceil((i - 70000000000.0 )/1000000000.0) * 60000.0;
	}
	else if(i>100000000000.0 && i<=200000000000.0)
	{
		rate = 9100000.0 + Math.ceil((i - 100000000000.0 )/1000000000.0) * 50000.0;
	}
	else if(i>200000000000.0 && i<=500000000000.0)
	{
		rate = 14100000.0 + Math.ceil((i - 200000000000.0 )/1000000000.0) * 40000.0;
	}
	else if(i>500000000000.0)
	{
		rate = 26100000.0 + Math.ceil((i - 500000000000.0 )/1000000000.0) * 20000.0;
	}

	if(rate > 50000000){
		rate = "50000000";	 //최고한도액 5천만원
	}

	if(type > 3) //신주인수권증권
	{
		rate = Math.floor(rate/3/100) * 100;
	}

	return rate;
} 

/* [수수료계산] 상장-유가시장 */
function rate_Stcok(i) {
	let rate = "0.0";

	if(i <= 3000000000.0)
	{
		if(i <= 100000000.0)
		{
			rate = 250000.0;
		}
		else if(i > 100000000.0 && i <= 1000000000.0)
		{
			rate = 500000.0;
		}
		else
		{
			rate= (Math.ceil(i/1000000000.0)) * 500000.0;
		}
	}
	else if(3000000000.0 < i && i <= 20000000000.0)
	{
			rate =1500000.0+ Math.ceil((i-3000000000.0)/1000000000.0) * 210000.0;
	}
	else if(20000000000.0 < i && i <= 50000000000.0)
	{
			rate = 5070000.0 +Math.ceil((i-20000000000.0)/1000000000.0) * 180000.0;
	}
	else if(50000000000.0 < i && i <= 100000000000.0)
	{
			rate = 10470000.0 + Math.ceil((i-50000000000.0)/1000000000.0) * 150000.0;
	}		
	else if(100000000000.0 < i && i <= 200000000000.0)
	{
			rate = 17970000.0 + Math.ceil((i-100000000000.0)/1000000000.0) * 120000.0;
	}
	else if(200000000000.0 < i && i <= 500000000000.0)
	{
			rate = 29970000.0 + Math.ceil((i-200000000000.0)/1000000000.0) * 80000.0;
	}
	else if(500000000000.0 < i)
	{
			rate = 53970000.0 + Math.ceil((i-500000000000.0)/1000000000.0) * 30000.0;
	}

	//신주상장수수료 최대한도
	if(rate > 80000000.0)
	{
			rate = 80000000.0;
	}

  return rate;

}

