/* [수수료계산] ETF or ETN */
function rate_comm(obj)
{
	let rtn_comm = 0.0;
	let rtn_comm_value = 0.0;

	if(obj <= 50000000000.0)
	{
		rtn_comm = 1000000.0 / 3.0;
	}
	else if(obj > 50000000000.0 && obj <= 100000000000.0)
	{
		rtn_comm = (5000000.0 + Math.ceil((obj-50000000000.0)/1000000000.0) * 75000.0) / 3.0;
	}
	else if(obj > 100000000000.0 && obj <= 200000000000.0)
	{
		rtn_comm = (8750000.0+ Math.ceil((obj-100000000000.0)/1000000000.0) * 60000.0) / 3.0;
	}
	else if(obj > 200000000000.0 && obj <= 500000000000.0)
	{
		rtn_comm = (14750000.0+ Math.ceil((obj-200000000000.0)/1000000000.0) * 45000.0) / 3.0;
	}
	else if(obj > 500000000000.0 && obj <= 2000000000000.0)
	{
		rtn_comm = (28250000.0+ Math.ceil((obj-500000000000.0)/1000000000.0) * 35000.0) / 3.0;
	}
	else if(obj > 2000000000000.0 && obj <= 5000000000000.0)
	{
		rtn_comm = (80750000.0+ Math.ceil((obj-2000000000000.0)/1000000000.0) * 25000.0) / 3.0;
	}
	else if(obj > 5000000000000.0 && obj <= 10000000000000.0)
	{
		rtn_comm = (155750000.0+ Math.ceil((obj-5000000000000.0)/1000000000.0) * 15000.0) / 3.0;
	}	
	else if(obj > 10000000000000.0)
	{
	    rtn_comm = (230750000.0+ Math.ceil((obj-10000000000000.0)/1000000000.0) * 5000.0) / 3.0;
	}

	rtn_comm_value = Math.floor((rtn_comm)/100) * 100 ;

	//상장수수료 최대한도 : 83,333,300원
	if(Number(rtn_comm_value) > Number(83333300)) {
		rtn_comm_value = 83333300;	
	}

	return rtn_comm_value;
}

/* [수수료계산] ELW */
function rate_comm_elw(obj)
{
	let rtn_comm = 0.0;
	let rtn_comm_value = 0.0;

	if (obj >= 1000000000.0 && obj < 2000000000.0)
	{
			rtn_comm = 200000;
	}
	else if(obj >= 2000000000.0 && obj < 5000000000.0)
	{
			rtn_comm = 310000.0 + Math.floor((obj-2000000000.0)/1000000000.0) * 90000.0;
	}
	else if(obj >= 5000000000.0 && obj < 10000000000.0)
	{
			rtn_comm = 580000.0 + Math.floor((obj-5000000000.0)/1000000000.0) * 80000.0;
	}		
	else if(obj >= 10000000000.0 && obj < 50000000000.0)
	{
			rtn_comm = 980000.0 + Math.floor((obj-10000000000.0)/1000000000.0) * 70000.0;
	}
	else if(obj >= 50000000000.0 && obj < 100000000000.0)
	{
			rtn_comm = 3780000.0 + Math.floor((obj-50000000000.0)/1000000000.0) * 30000.0;
	}
	else if (obj >= 100000000000.0)
	{
			rtn_comm = 5280000.0 + Math.floor((obj-100000000000.0)/1000000000.0) * 10000.0;
	}

	rtn_comm_value = Math.floor((rtn_comm)/100) * 100 ;

	return rtn_comm_value;
}

/* [수수료계산] 신주인수권, 수익증권 */
function rate_Bw(i) {
	let rate = 0.0;
	if (i < 3000000000.0) {
        rate = 0;
    } else if (i >= 3000000000.0 && i < 5000000000.0) {
        rate = 300000;
    } else if (i >= 5000000000.0 && i < 10000000000.0) {
        rate = 700000;
    } else if (i >= 10000000000.0 && i < 15000000000.0) {
        rate = 1000000;
    } else if (i >= 15000000000.0 && i < 25000000000.0) {
        rate = 1200000;
    } else if (i >= 25000000000.0 && i < 50000000000.0) {
        rate = 1300000;
    } else if (i >= 50000000000.0 && i < 100000000000.0) {
        rate = 1400000;
    } else if (i >= 100000000000.0 && i < 200000000000.0) {
        rate = 1500000;
    } else if (i >= 200000000000.0 && i < 500000000000.0) {
        rate = 1600000;
    } else if (i >= 500000000000.0) {
        rate = 1700000;
    }
	return rate;
}

function unformat(obj) {
	let temp = "";
	const n = String(obj.value);
	const len = n.length;
	let pos = 0;
  	let ch = '';

	while (pos < len) {
		ch = n.charAt(pos);

		if(scwin.mkt === '2' && scwin.kk === '2') {		//코스닥 외국주권은 소수점 허용
			if (((ch >= '0') && (ch <= '9')) || (ch === '-') || (ch === '.') ) temp = temp + ch;
		} else {
			if (((ch >= '0') && (ch <= '9')) || (ch === '-') ) temp = temp + ch;
		}

		pos = pos + 1;
	}
	obj.setValue(temp);

	return true;
}

/* 숫자 format */
function numFormat(obj) {
    if(obj.value !== "" && !isMinusNum(obj.value)) {
        obj.setValue("");
        alert("숫자만 입력가능합니다.");
        obj.focus();
        return;
	}

	unformat(obj);

	if(obj.value === "") return;
	if(isNaN(obj.value)) {
		obj.setValue("");
		return;
	}

	if(Number(obj.value) > 999999999999999 || Number(obj.value) < -999999999999999) {
		obj.setValue("");
		alert("입력한 숫자가 범위를 초과하였습니다.");
		obj.focus();
		return;
	}


	let str = Number(obj.value) + "";
	let sMinusChar = "";

	if(Number(obj.value) < 0) {
		str = str.substring(1);
		sMinusChar = "-";
	}

	let tempStr = str;
	let fltStr = "";		//소수점이하 숫자

	if(str.indexOf(".") > -1) {
		tempStr = str.substr(0, str.indexOf("."));		//소수점포함된경우, 소수점위의 문자만 저장
		fltStr = str.substr(str.indexOf("."));
	}

	//var leng = str.length;
	const leng = tempStr.length;		//소수점위의 문자열만 카운트

	const size = 3;
	const cnt = Math.floor(leng / size);

	let pos = leng % size;
	let result = "";

	if(cnt === 0) {		//천단위 미만은 입력숫자 그대로
		obj.setValue(Number(obj.value));
		return;
	}
	for(let i = cnt ; i > 0 ; i = i-1 ){
		//result = "," + str.substr(pos+(i-1)*size, size) + result ;
		result = "," + tempStr.substr(pos+(i-1)*size, size) + result ;
	}

	if(result !== '') {
		if( pos === 0) {
			//obj.value = sMinusChar + result.substring(1);
			obj.setValue(sMinusChar + result.substring(1) + fltStr);
		}else{
			//obj.value = sMinusChar + str.substr(0,pos) + result;
			obj.setValue(sMinusChar + str.substr(0,pos) + result + fltStr);
		}
	}
	return;
}

function checkMax(type, obj){
	if (type === '1'){
		if (obj.value.length > 14){
			alert ('상장주식 수는 100억원  미만이어야 합니다.');
			obj.focus();
			return;
		}
	}
	else if (type === '2'){
		if (obj.value.length > 7){
			alert ('종가는 100 만원 미만이어야 합니다.');
			obj.focus();
			return;
		}
	}
}


function isMinusNum(name) {
    let ch = "\0";
	let flag = true;
	ch = name.charAt(0);
	flag = ((ch >= '0' && ch <= '9') || ch === '-')?true:false;
    for (let i = 1, ch = name.charAt(i);
        (i < name.length) && (flag); ch = name.charAt(++i)) {
        if ((ch >= '0') && (ch <= '9'))
        	;
        else
            flag = false;
    }
    return flag;
}

